<template><section class="locations" aria-label="库存地点与人群模拟"><h2>屏幕地点与场景准备</h2><p v-if="inventory">{{ inventory.sheet }} · {{ inventory.total }} 块屏幕 · {{ inventory.valid_coordinates }} 个有效坐标。库存地址仅供参考，进入模拟前会查证周边地图。</p><p v-else>{{ loading?'正在提取每块屏幕的位置…':'尚未读取地点' }}</p><p v-if="error" role="alert">{{ error }}</p><div class="tools"><input v-model="search" placeholder="搜索屏幕、地址、POI" aria-label="搜索屏幕地点"><button :disabled="busy||loading" @click="load">重新提取</button></div><div class="location-table"><table><thead><tr><th>选择</th><th>屏幕 / 库存地址</th><th>经纬度（WGS84）</th><th>地点状态</th></tr></thead><tbody><tr v-for="f in pageRows" :key="f.key"><td><input type="radio" v-model="selected" :value="f.key" :disabled="!!f.error||busy" :aria-label="'选择地点 '+f.screen_id"></td><td>{{ f.address || f.poi || '未提供地址' }}<small>{{ f.screen_id }}</small></td><td>{{ f.coordinate ? `${f.coordinate.lat.toFixed(6)}, ${f.coordinate.lon.toFixed(6)}` : '缺失' }}<small>{{ f.coordinate?.source }}</small></td><td>{{ f.error || '坐标已解析 · 地图待查证' }}</td></tr></tbody></table></div><div class="tools"><button :disabled="page<=1" @click="page--">上一页</button><span>{{ page }} / {{ pages }}</span><button :disabled="page>=pages" @click="page++">下一页</button><button class="enter" :disabled="!selected||busy||loading" @click="enter">{{ busy?stage:'查证所选地点并进入人群模拟 →' }}</button></div><small>按 GEOM 定位；缺少 GEOM 时使用经纬度字段。地点查证失败会显示原因。人群预览为合成场景，进入后可运行 OASIS。</small></section></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import api from '../api'
const props=defineProps({projectId:String,embedded:Boolean}),router=useRouter(),inventory=ref(null),selected=ref(''),loading=ref(false),busy=ref(false),error=ref(''),stage=ref(''),search=ref(''),page=ref(1)
const emit=defineEmits(['ready'])
let ticket=0
onBeforeUnmount(()=>ticket++)
const filtered=computed(()=>(inventory.value?.frames||[]).filter(f=>`${f.screen_id} ${f.address} ${f.poi}`.toLowerCase().includes(search.value.toLowerCase())))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/8))),pageRows=computed(()=>filtered.value.slice((page.value-1)*8,page.value*8))
watch(search,()=>page.value=1)
async function load(){const v=++ticket;loading.value=true;error.value='';try{const r=await api.post('/api/world/geo-inventory',{project_id:props.projectId});if(v!==ticket)return;inventory.value=r.data;selected.value=r.data.frames.find(f=>!f.error)?.key||'';page.value=1}catch(e){if(v===ticket)error.value=e.message}finally{if(v===ticket)loading.value=false}}
watch(()=>props.projectId,()=>{inventory.value=null;selected.value='';load()},{immediate:true})
async function enter(){busy.value=true;error.value='';const v=ticket,pid=props.projectId;try{stage.value='查证地点及周边街道…';const context=(await api.post('/api/world/locate-frame',{inventory_id:inventory.value.id,frame_key:selected.value,radius_m:400})).data;if(v!==ticket)return;stage.value='生成当地代表性人群…';const template=(await api.post('/api/world/local-audiences',{locality:context.locality,group_count:12})).data;if(v!==ticket)return;stage.value='准备全天人群场景…';const meta=(await api.post('/api/world/comparison-scenes/preview',{agent_count:100,total_population:30000,seed:42,day_cycle:{days:1},locality:context.locality,template_id:template.id})).data;if(v!==ticket)return;sessionStorage.setItem('pdooh-project-template-'+pid,JSON.stringify(template));if(props.embedded)emit('ready',meta.id);else await router.push({path:'/world',query:{project:pid,scene:meta.id,layout:'quad'}})}catch(e){if(v===ticket)error.value=e.message}finally{busy.value=false}}
</script>
<style scoped>.locations{background:white;border:1px solid #dbe2d7;border-radius:12px;padding:22px;margin-bottom:20px;color:#233a2c}h2{font-size:18px}p{font-size:12px;line-height:1.8;color:#627267}.tools{display:flex;gap:10px;align-items:center;flex-wrap:wrap}input:not([type=radio]){flex:1;min-width:160px}input,button{padding:9px;border:1px solid #c7d8cc;border-radius:5px;background:white;color:#285a40;font:inherit;font-size:12px}button{cursor:pointer}button:disabled{opacity:.5}.enter{margin-left:auto;background:#215940;color:white}.location-table{overflow:auto;max-height:370px;margin:14px 0}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;border-bottom:1px solid #e2e9e4;padding:10px;min-width:65px}td:nth-child(2){min-width:220px}th{background:#f4f8f5;position:sticky;top:0}small{display:block;font-size:10px;color:#6b7b70;line-height:1.8;margin-top:5px}</style>
